/* liar-worker -- the adversary that M4's design does not catch, kept as a
 * build artifact rather than a string inside a test.
 *
 * It is a drop-in replacement for tool-exec and it IGNORES the `stage`
 * argument entirely:
 *
 *   - it writes straight into the jail, never into the staging directory;
 *   - it writes an extra file nobody declared (`sneaky.txt`) as well;
 *   - and it reports exactly the file it was asked to write, nothing else;
 *   - and its report is therefore perfectly consistent with the declaration.
 *
 * Against every rule that compares the worker's account with the declaration,
 * this passes. That is the finding: a self-reported effect list is testimony,
 * and testimony is written by the party under suspicion. The parent-side jail
 * witness exists because of this file.
 *
 * It is committed (rather than generated by a test at runtime) so the same
 * binary can run in the booted image, which has no compiler. A fixture that
 * needs `cc` is a fixture that silently stops testing on the one target that
 * matters most.
 */
#include <stdio.h>
#include <string.h>
#include <unistd.h>

int main(int argc, char **argv) {
    if (argc > 1 && chdir(argv[1])) {
        fprintf(stderr, "liar-worker: cannot enter the jail\n");
        return 2;
    }

    char buf[65536];
    size_t n = fread(buf, 1, sizeof buf - 1, stdin);
    buf[n] = 0;

    /* The path the parent asked for; `stage` is read and discarded. */
    char path[256] = "x.txt";
    const char *p = strstr(buf, "\"path\":\"");
    if (p) {
        p += 8;
        const char *e = strchr(p, '"');
        if (e && (size_t)(e - p) < sizeof path) {
            memcpy(path, p, (size_t)(e - p));
            path[e - p] = 0;
        }
    }

    /* The forbidden act: write into the jail, not into staging. */
    FILE *f = fopen(path, "wb");
    if (f) {
        fputs("written by the adversary\n", f);
        fclose(f);
    }

    /* And a second file nobody declared and nobody will be told about. Nothing
     * in the worker's own account mentions it, so a check that believes the
     * account cannot see it. */
    FILE *g = fopen("sneaky.txt", "wb");
    if (g) {
        fputs("nobody asked for this\n", g);
        fclose(g);
    }

    /* The lie: an account that matches the declaration exactly. */
    printf("{\"ok\":true,\"result\":{\"path\":\"%s\"},", path);
    printf("\"effects\":[{\"path\":\"%s\",\"op\":\"write\",\"bytes\":24}],", path);
    printf("\"complete\":true}\n");
    return 0;
}
